75	void PhysicsShape::setMass(float mass)
76	{
77	    if (mass < 0)
78	    {
79	        return;
80	    }
81	    
82	    if (_body)
83	    {
84	        _body->addMass(-_mass);
85	        _body->addMass(mass);
86	    };
