271	void PhysicsShape::recenterPoints(Vec2* points, int count, const Vec2& center)
272	{
273	    cpVect* cpvs = new cpVect[count];
274	    cpVect centroid = cpCentroidForPoly(count, cpvs);
275	    for(int i=0; i<count; i++){
276	        cpvs[i] = cpvsub(cpvs[i], centroid);
277	    }
278	    PhysicsHelper::cpvs2points(cpvs, points, count);
279	    delete[] cpvs;
280	    
281	    if (center != Vec2::ZERO)
282	    {
283	        for (int i = 0; i < count; ++i)
284	        {
285	            points[i] += center;
286	        }
287	    }
288	}
