299	void PhysicsShape::setBody(PhysicsBody *body)
300	{
301	    // already added
302	    if (body && _body == body)
303	    {
304	        return;
305	    }
306	    
307	    if (_body)
308	    {
309	        _body->removeShape(this);
310	    }
