333	bool PhysicsShapeCircle::init(float radius, const PhysicsMaterial& material/* = MaterialDefault*/, const Vec2& offset /*= Vec2(0, 0)*/)
334	{
335	    do
336	    {
337	        _type = Type::CIRCLE;
338	        
339	        auto shape = cpCircleShapeNew(s_sharedBody, radius, PhysicsHelper::point2cpv(offset));
340	        CC_BREAK_IF(shape == nullptr);
341	        cpShapeSetUserData(shape, this);
342	        
343	        addShape(shape);
344	        
345	        _area = calculateArea();
346	        _mass = material.density == PHYSICS_INFINITY ? PHYSICS_INFINITY : material.density * _area;
347	        _moment = calculateDefaultMoment();
348	        
349	        setMaterial(material);
350	        return true;
351	    } while (false);
352	    
353	    return false;
354	}
