396	void PhysicsShapeCircle::updateScale()
397	{
398	    cpFloat factor = std::abs(_newScaleX / _scaleX);
399	
400	    cpShape* shape = _cpShapes.front();
401	    cpVect v = cpCircleShapeGetOffset(shape);
402	    v = cpvmult(v, factor);
403	    cpCircleShapeSetOffset(shape, v);
404	
405	    cpCircleShapeSetRadius(shape, cpCircleShapeGetRadius(shape) * factor);
406	
407	    PhysicsShape::updateScale();
408	}
