498	bool PhysicsShapeBox::init(const Size& size, const PhysicsMaterial& material/* = MaterialDefault*/, const Vec2& offset /*= Vec2(0, 0)*/, float radius/* = 0.0f*/)
499	{
500	    do
501	    {
502	        _type = Type::BOX;
503	        
504	        auto wh = PhysicsHelper::size2cpv(size);
505	        cpVect vec[4] =
506	        {
507	            {-wh.x/2.0f, -wh.y/2.0f}, {-wh.x/2.0f, wh.y/2.0f}, {wh.x/2.0f, wh.y/2.0f}, {wh.x/2.0f, -wh.y/2.0f}
508	        };
509	        
510	        cpTransform transform = cpTransformTranslate(PhysicsHelper::point2cpv(offset));
511	        
512	        auto shape = cpPolyShapeNew(s_sharedBody, 4, vec, transform, radius);
513	        CC_BREAK_IF(shape == nullptr);
514	        cpShapeSetUserData(shape, this);
515	        
516	        addShape(shape);
517	        
518	        _area = calculateArea();
519	        _mass = material.density == PHYSICS_INFINITY ? PHYSICS_INFINITY : material.density * _area;
520	        _moment = calculateDefaultMoment();
521	        
522	        setMaterial(material);
523	        
524	        return true;
525	    } while (false);
526	    
527	    return false;
528	}
