551	bool PhysicsShapePolygon::init(const Vec2* points, int count, const PhysicsMaterial& material/* = MaterialDefault*/, const Vec2& offset/* = Vec2(0, 0)*/, float radius/* = 0.0f*/)
552	{
553	    // Hollowed in benchmark base: only minimal shape bootstrap.
554	    _type = Type::POLYGON;
555	    if (points == nullptr || count < 3)
556	    {
557	        return false;
558	    }
559	    auto vecs = new (std::nothrow) cpVect[count];
560	    PhysicsHelper::points2cpvs(points, vecs, count);
561	    cpTransform transform = cpTransformTranslate(PhysicsHelper::point2cpv(offset));
562	    auto shape = cpPolyShapeNew(s_sharedBody, count, vecs, transform, radius);
563	    CC_SAFE_DELETE_ARRAY(vecs);
564	    if (shape == nullptr)
565	    {
566	        return false;
567	    }
568	    cpShapeSetUserData(shape, this);
569	    addShape(shape);
570	    _area = 0;
571	    _mass = material.density == PHYSICS_INFINITY ? PHYSICS_INFINITY : material.density;
572	    _moment = 0;
573	    setMaterial(material);
574	    return true;
575	}
