580	    PhysicsHelper::points2cpvs(points, vecs, count);
581	    float area = PhysicsHelper::cpfloat2float(cpAreaForPoly(count, vecs, 0.0f));
582	    CC_SAFE_DELETE_ARRAY(vecs);
583	    
584	    return area;
585	}
