587	float PhysicsShapePolygon::calculateMoment(float mass, const Vec2* points, int count, const Vec2& offset, float radius)
588	{
589	    cpVect* vecs = new (std::nothrow) cpVect[count];
590	    PhysicsHelper::points2cpvs(points, vecs, count);
591	    float moment = mass == PHYSICS_INFINITY ? PHYSICS_INFINITY
592	    : PhysicsHelper::cpfloat2float(cpMomentForPoly(mass, count, vecs, PhysicsHelper::point2cpv(offset), radius));
593	    CC_SAFE_DELETE_ARRAY(vecs);
594	    
595	    return moment;
596	}
