598	float PhysicsShapePolygon::calculateArea()
599	{
600	    auto shape = _cpShapes.front();
601	    int count = cpPolyShapeGetCount(shape);
602	    cpVect* vecs = new cpVect[count];
603	    for(int i=0;i<count;++i)
604	        vecs[i] = cpPolyShapeGetVert(shape, i);
605	    float area = PhysicsHelper::cpfloat2float(cpAreaForPoly(count, vecs, cpPolyShapeGetRadius(shape)));
606	    CC_SAFE_DELETE_ARRAY(vecs);
607	    return area;
608	}
609	
610	float PhysicsShapePolygon::calculateDefaultMoment()
611	{
612	    if(_mass == PHYSICS_INFINITY)
613	    {
614	        return PHYSICS_INFINITY;
615	    }
616	    else
617	    {
618	        auto shape = _cpShapes.front();
619	        int count = cpPolyShapeGetCount(shape);
620	        cpVect* vecs = new cpVect[count];
621	        for(int i=0;i<count;++i)
622	            vecs[i] = cpPolyShapeGetVert(shape, i);
623	        float moment = PhysicsHelper::cpfloat2float(cpMomentForPoly(_mass, count, vecs, cpvzero, cpPolyShapeGetRadius(shape)));
624	        CC_SAFE_DELETE_ARRAY(vecs);
625	        return moment;
626	    }
627	}
